def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Collect full opponent history once
    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_last, opp_last = history[-1]
    opp_rate = (opp_c + 1.0) / (n + 2.0)

    # Detect a full defection streak at the end
    streak_d = 0
    for x in reversed(opp):
        if x == 'D':
            streak_d += 1
        else:
            break

    # Detect a full cooperation streak at the end
    streak_c = 0
    for x in reversed(opp):
        if x == 'C':
            streak_c += 1
        else:
            break

    # Always-defector: defect immediately and permanently
    if opp_c == 0:
        return 'D'

    # All-cooperator (rare probes to exploit, but stay safe)
    if opp_d == 0:
        if n >= 20 and n < 90 and n % 19 == 0:
            return 'D'
        return 'C'

    # Heavily exploited recently? Look at last 12 rounds
    start = n - 12
    if start < 0:
        start = 0
    recent = opp[start:]
    rec_d = recent.count('D')
    rec_c = len(recent) - rec_d

    # Determine opponent's likely response to our defection last round
    # (classify as retaliator vs forgiving) using pre-last history
    # -- only compute when n >= 3
    retaliation_score = 0
    forgive_score = 0
    if n >= 3:
        for i in range(1, n):
            if my[i - 1] == 'D' and opp[i] == 'D':
                retaliation_score += 1
            elif my[i - 1] == 'D' and opp[i] == 'C':
                forgive_score += 1

    # Endgame: last 6 rounds, greed if opponent tends to cooperate
    if n >= 100 - 6:
        if opp_rate >= 0.5:
            return 'D'
        return 'C'

    # Strong punishment: long recent defection run
    if streak_d >= 3:
        return 'D'
    if streak_d == 2:
        # Punish, but plan to forgive right after
        return 'D'

    # streak_d == 1: single recent defection
    if opp_last == 'D':
        # Exploitation signal: opponent defected while we cooperated
        if my_last == 'C':
            # If opponent has been very cooperative overall, forgive sometimes
            if opp_rate >= 0.7 and rng.random() < 0.5:
                return 'C'
            # If opponent just tolerated our defection, they may be soft
            if n >= 2 and my[-2] == 'D' and opp_last == 'D':
                return 'D'
            return 'D'
        else:
            # We defected, opponent retaliated. Return to cooperation to stop escalation.
            return 'C'

    # Opponent cooperated last round (streak_d == 0)
    # If we defected last, do not keep exploiting too much: restore cooperation
    if my_last == 'D':
        # But if opponent never retaliates to our defections, exploit a bit more
        if retaliation_score <= 1 and forgive_score >= 2 and rng.random() < 0.45:
            return 'D'
        return 'C'

    # Mutual cooperation zone; consider occasional probing
    if opp_rate >= 0.7:
        # Very cooperative partner: stay cooperating, rare, safe probe
        if n >= 30 and n < 85 and streak_c >= 6 and n % 23 == 0:
            return 'D'
        return 'C'

    # Moderate opponent: cooperative but has defected
    # If recent cooperation is strong, cooperate; else cautiously defect with low prob
    if rec_c >= rec_d + 4:
        return 'C'

    # Mixed opponent: mirror-lite — cooperate when last was C, but guard against runs
    if opp_rate >= 0.5 and rng.random() < 0.85:
        return 'C'

    # Opponent mostly defecting overall: defect but test occasionally
    if rng.random() < 0.85:
        return 'D'
    return 'C'
